        for (int i = pLen; i < sLen; i++) {
            sChars[s[i] - 'a']++;
            sChars[s[i - pLen] - 'a']--;
            if (sChars == pChars) ans.push_back(i - pLen + 1);
        }
        return ans;
    }
};

