class Solution(object):
    def findAnagrams(self, s, p):
        """
        :type s: str
        :type p: str
        :rtype: List[int]
        """
        if len(s) < len(p):
            return []
        s_dict, p_dict = [0] * 26, [0] * 26
        ans = []
        for i in range(len(p)):
            s_dict[ord(s[i]) - ord('a')] += 1
            p_dict[ord(p[i]) - ord('a')] += 1
        for i in range(len(s) - len(p) + 1):
            if s_dict == p_dict:
                ans.append(i)
            if i + len(p) < len(s):
                s_dict[ord(s[i]) - ord('a')] -= 1
                s_dict[ord(s[i + len(p)]) - ord('a')] += 1
        return ans
